set-variable.value:
#[%dw 2.0
output application/java
---
"SELECT Id FROM Account WHERE " ++ (
    [
        if (vars.cieReferral.account_id != null) "Id = '" ++ vars.cieReferral.account_id ++ "'" else null,
        if (vars.cieReferral.Medi_Cal_CIN != null) "Medi_Cal_CIN__pc = '" ++ vars.matchedReferral.Medi_Cal_CIN ++ "'" else null,
        if (vars.cieReferral.Last_Name != null) "LastName = '" ++ vars.matchedReferral.Last_Name ++ "'" else null,
        if (vars.cieReferral.Birthdate != null) "PersonBirthdate = " ++ vars.matchedReferral.Birthdate else null
    ] filter ($ != null) joinBy " AND "
)]
